function HomeScreen({ onEventPress, scrollPositionRef }) {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(0);
  const [timeFilter, setTimeFilter] = useState(null);
  const [selectedCategories, setSelectedCategories] = useState([]);
  const [selectedProvider, setSelectedProvider] = useState(null);
  const [showProviderDropdown, setShowProviderDropdown] = useState(false);
  const sectionListRef = useRef(null);
  const scrollPositionRefLocal = useRef(0);

  const loadEvents = useCallback(async (pageNum = 0, isLoadMore = false) => {
    if (isLoadMore) {
      setLoadingMore(true);
    } else {
      setLoading(true);
    }

    try {
      const result = await fetchAllEventsViaServer();
      const data = result.events || [];

      if (isLoadMore) {
        setEvents(prev => [...prev, ...data]);
      } else {
        setEvents(data);
      }
      setPage(pageNum);
    } catch (err) {
      setError(err.message);
      console.error('Failed to load events:', err);
    } finally {
      setLoading(false);
      setLoadingMore(false);
    }
  }, []);

